import{_ as d,o,c as t,ai as c}from"./chunks/framework.DAbPic9L.js";const u=JSON.parse('{"title":"核心计划","description":"","frontmatter":{},"headers":[],"relativePath":"plan/core.md","filePath":"plan/core.md","lastUpdated":1783087135000}'),a={name:"plan/core.md"};function l(i,e,p,r,n,h){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="核心计划" tabindex="-1">核心计划 <a class="header-anchor" href="#核心计划" aria-label="Permalink to &quot;核心计划&quot;">​</a></h1><h2 id="产品描述" tabindex="-1">产品描述 <a class="header-anchor" href="#产品描述" aria-label="Permalink to &quot;产品描述&quot;">​</a></h2><p>我构建一个租户级平台系统，用于管理、接入其它项目；这些项目的用户，在该平台系统统一管理、认证、授权等。</p><p>为了持续开发以及未来盈利，我开发的项目必须精简极致，且能够跨应用服务，以保证能够长期持续获客以及最大化付费意愿。</p><p>我将使用<code>MVP</code>方案快速测试产品可行性，以便在产品上线前进行优化和调整。</p><p>因此，我前期必须构建<code>2</code>个产出内容: 租户系统的骨架核心(<code>用户</code>、<code>登录</code>、<code>API Key</code>)和可盈利的<code>MVP</code>产品。</p><h2 id="产品可行性分析" tabindex="-1">产品可行性分析 <a class="header-anchor" href="#产品可行性分析" aria-label="Permalink to &quot;产品可行性分析&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品维度</th><th>客观评价</th><th>调整建议</th></tr></thead><tbody><tr><td>核心价值</td><td>减少重复工作，缩短上线周期。</td><td>保持核心目标。</td></tr><tr><td>市场潜力</td><td>小团队及开发者需要现成平台。</td><td>未来可按套件卖出盈利。</td></tr><tr><td>技术难度</td><td>涉及租户隔离，网关按量计费等逻辑，安全稳定性要求高。</td><td>初期逻辑隔离，严禁过度设计。</td></tr><tr><td>资产收支</td><td>初期为负，中期稳定付费，后续持续盈利。</td><td>设计可盈利<code>MVP</code>产品；流量优先，稳定付费。 <br> 盈利模式: <br> 1. 知识付费(<code>在线学习</code>)。 <br> 3. 产品付费(<code>套件售卖</code>、<code>资源付费</code>、<code>接口付费</code>)。</td></tr></tbody></table><h2 id="落地线路规划" tabindex="-1">落地线路规划 <a class="header-anchor" href="#落地线路规划" aria-label="Permalink to &quot;落地线路规划&quot;">​</a></h2><ol><li><p>可盈利<code>MVP</code>方案选品，精简极致。</p></li><li><p>租户系统平台核心功能，精简对接。</p></li><li><p>产品内核标准化，功能封装成库包。</p></li><li><p><code>MVP</code>新品接入系统，通用性测试。</p></li><li><p>发布首个产品，裂变获客持续引流。</p></li><li><p>桌面应用开箱即用，代码套件售卖。</p></li><li><p>更多<code>MVP</code>产品接入，并持续迭代。</p></li><li><p>跨行接入物联网，实现跨应用服务。</p></li><li><p>最终实现用户统一使用我们的产品。</p></li></ol><br><p><strong>前置能力</strong></p><p>你必须理解业务流程，会经过哪些服务，以及事件触发和通信交互等内容，才能将业务固定流程标准化。对于不同种方式处理，通过依赖倒置来替换策略方案。</p><ul><li><p>业务流程图: 先画功能设计流程(<code>角色-动作-分支-状态</code>)，再画系统分析流程(<code>服务-事件-分支-通信</code>)，后定义<code>API</code>接口清单。</p><ul><li><p>功能设计流程: 角色<code>-&gt;</code>动作<code>-&gt;</code>分支<code>-&gt;</code>状态.</p></li><li><p>系统分析流程: 服务<code>-&gt;</code>事件<code>-&gt;</code>分支<code>-&gt;</code>通信(<code>同步、异步</code>).</p></li><li><p><code>API</code>接口清单: 提供方<code>-&gt;</code>调用方<code>-&gt;</code>接口名称<code>-&gt;</code>接口路径(<code>入方法)</code>-&gt;<code>接口参数(</code>输入<code>)</code>-&gt;<code>接口返回值(</code>输出`)。</p></li></ul></li><li><p>业务原型设计: 在业务流程图基础上，设计布局原型内容。</p><ul><li><p>业务原型组织架构(<code>xx管理-&gt;xx新建，列表，详情-&gt;功能操作、信息聚合</code>)。</p></li><li><p>业务原型布局设计: 根据将组织架构以及模块功能，拖放布局内容要素，并埋点交互。</p></li></ul></li><li><p>领域驱动设计: 先画战略设计(边界、上下文、职责、事件)，再画战术设计(聚合、实体等)。</p><ul><li><p>核心领域概念清单，统一领域语言。</p></li><li><p>边界定责(<code>有限界上下文</code>)，持有数据，统一语言清单；跨服务只能通过<code>API</code>访问或事件访问。</p></li><li><p>贯穿上下文的标识: 租户(<code>tenant_id</code>)、用户(<code>user_id</code>)等。</p></li><li><p>值对象(<code>value-object</code>)自检数据输入合法性；聚合(<code>aggregate</code>)保证聚合内一致性；领域事件(<code>event</code>)解耦跨服务逻辑。</p></li><li><p>组合优先于继承，依赖倒置可替换对象，应用不同策略；数据层抽象操作，以适配不同数据库。</p></li></ul></li></ul><h2 id="租户系统分析与设计" tabindex="-1">租户系统分析与设计 <a class="header-anchor" href="#租户系统分析与设计" aria-label="Permalink to &quot;租户系统分析与设计&quot;">​</a></h2><h2 id="mvp产品分析与设计" tabindex="-1">MVP产品分析与设计 <a class="header-anchor" href="#mvp产品分析与设计" aria-label="Permalink to &quot;MVP产品分析与设计&quot;">​</a></h2>',16)])])}const _=d(a,[["render",l]]);export{u as __pageData,_ as default};
